-- Placeholders like {{ run_id }} are filled in by the ELT DAG at run time.
-- Adds one f_<check> column per rule, plus dq_status, failure_reason, warning_reason
CREATE OR REPLACE TABLE stg_payments_flagged AS
SELECT *,
  CASE WHEN "f_payment_id_not_null" OR "f_payment_order_id_not_null" OR "f_payment_id_unique" OR "f_payment_ts_valid" OR "f_payment_status_allowed" OR "f_success_amount_positive" OR "f_payment_order_exists" OR "f_payment_ts_not_future" THEN 'FAIL' WHEN "f_gateway_ref_present" OR "f_payment_mode_known" OR "f_payment_mode_standard" OR "f_success_amount_matches_order" THEN 'WARN' ELSE 'PASS' END AS dq_status,
  NULLIF(concat_ws('; ', CASE WHEN "f_payment_id_not_null" THEN 'payment_id_not_null' END, CASE WHEN "f_payment_order_id_not_null" THEN 'payment_order_id_not_null' END, CASE WHEN "f_payment_id_unique" THEN 'payment_id_unique' END, CASE WHEN "f_payment_ts_valid" THEN 'payment_ts_valid' END, CASE WHEN "f_payment_status_allowed" THEN 'payment_status_allowed' END, CASE WHEN "f_success_amount_positive" THEN 'success_amount_positive' END, CASE WHEN "f_payment_order_exists" THEN 'payment_order_exists' END, CASE WHEN "f_payment_ts_not_future" THEN 'payment_ts_not_future' END), '') AS failure_reason,
  NULLIF(concat_ws('; ', CASE WHEN "f_gateway_ref_present" THEN 'gateway_ref_present' END, CASE WHEN "f_payment_mode_known" THEN 'payment_mode_known' END, CASE WHEN "f_payment_mode_standard" THEN 'payment_mode_standard' END, CASE WHEN "f_success_amount_matches_order" THEN 'success_amount_matches_order' END), '') AS warning_reason
FROM (
  SELECT t.*,
    COALESCE((t.payment_id IS NULL), FALSE) AS "f_payment_id_not_null",
    COALESCE((t.order_id IS NULL), FALSE) AS "f_payment_order_id_not_null",
    COALESCE((t.payment_status = 'SUCCESS' AND t.payment_mode IN ('UPI', 'Card', 'Wallet') AND t.gateway_ref IS NULL), FALSE) AS "f_gateway_ref_present",
    COALESCE((t.payment_id IS NOT NULL AND row_number() OVER (PARTITION BY t.payment_id ORDER BY t._row) > 1), FALSE) AS "f_payment_id_unique",
    COALESCE((t.payment_ts_raw IS NOT NULL AND t.payment_ts IS NULL), FALSE) AS "f_payment_ts_valid",
    COALESCE((t.payment_status IS NULL), FALSE) AS "f_payment_status_allowed",
    COALESCE((t.payment_mode IS NULL), FALSE) AS "f_payment_mode_known",
    COALESCE((t.payment_mode IS NOT NULL AND t.payment_mode_raw <> t.payment_mode), FALSE) AS "f_payment_mode_standard",
    COALESCE((t.payment_status = 'SUCCESS' AND (t.amount_paid IS NULL OR t.amount_paid <= 0)), FALSE) AS "f_success_amount_positive",
    COALESCE((t.order_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM ref_orders r WHERE r.order_id = t.order_id)), FALSE) AS "f_payment_order_exists",
    COALESCE((t.payment_status = 'SUCCESS' AND t.amount_paid IS NOT NULL AND EXISTS (SELECT 1 FROM ref_orders r WHERE r.order_id = t.order_id AND abs(t.amount_paid - r.order_amount) > 0.01)), FALSE) AS "f_success_amount_matches_order",
    COALESCE((t.payment_ts >= TIMESTAMP '{{ next_day }}'), FALSE) AS "f_payment_ts_not_future"
  FROM stg_payments_std t
) AS flagged;
